// ---------------------------------------------------------------------------
// Hints
// ---------------------------------------------------------------------------
function hintFor(zone: string): void {
  if (zone === LOBBY_ZONE) {
    narrate(
      "You",
      "Stage 1: Classroom 1A. The staircase is at the end of the lobby. Watch out — toilet paper rolls tumble down!",
    );
  } else if (zone === STAIRS) {
    narrate(
      "You",
      "Stage 2: Grand Staircase. Climbing up! There is a moving plank at the top — wait for it to swing.",
    );
  } else if (zone === HALLWAY) {
    narrate(
      "You",
      "Stage 3: Locker Corridor! The janitor left the floor wet. Do NOT touch the wet floor sign.",
    );
  } else if (zone === CAFETERIA) {
    narrate(
      "You",
      "Stage 4: Cafeteria! Lunch trays are moving on conveyor belts — ride them across.",
    );
  } else if (zone === GYM) {
    narrate(
      "You",
      "Stage 5: Gymnasium! Spinning turntables and moving platforms ahead.",
    );
  } else if (zone === LIBRARY) {
    narrate(
      "You",
      "Stage 6: Library! Hop across book stacks and dodge the rolling globe hazard.",
    );
  } else if (zone === MUD_ROOM) {
    narrate(
      "You",
      "Stage 7: Mud Room! The floor is thick quicksand. Use soap to slide across.",
    );
  } else if (zone === FINAL) {
    narrate("You", "Stage 8: Upper Hallway! Almost at the restroom door.");
  }
}

// ---------------------------------------------------------------------------
// Items
// ---------------------------------------------------------------------------
function useSoap(): void {
  if (held !== "soap") {
    narrate("You", "My hands are empty.");
    return;
  }
  take("soap", 1);
  dispatch("player-jump", { player: "", multiplier: 1.5 });
  narrate("You", "Slippery! But I can jump higher now.");
}

function useHallPass(): void {
  if (held !== "hall-pass") {
    narrate("You", "I do not have a hall pass.");
    return;
  }
  narrate("You", "The hall pass makes me feel slightly more legitimate.");
}

function used(entityId: string, _item: string): void {
  if (entityId === "soap") {
    dispatch("prop-remove", { id: "soap" });
    give("soap", "You pocket the soap bar.");
    return;
  }
  if (entityId === "wet-floor") {
    narrate("You", "That sign is not there to be touched.");
    return;
  }
  if (entityId === "globe") {
    narrate("You", "Ouch — that was the library globe.");
    return;
  }
  if (entityId === "tray-a" || entityId === "tray-b" || entityId === "tray-c") {
    narrate("You", "Leftover lunch. No time to eat.");
  }
}

function usedItem(item: string): void {
  if (item === "soap") {
    useSoap();
    return;
  }
  if (item === "hall-pass") {
    useHallPass();
    return;
  }
  narrate("You", "Now is not the time.");
}

// ---------------------------------------------------------------------------
// NPC dialogue
// ---------------------------------------------------------------------------
function talked(npcId: string): void {
  if (npcId === JANITOR) {
    narrate(
      "Janitor",
      "Wet floor ahead, kid. I just mopped it. Mind the sign.",
    );
    return;
  }
  if (npcId === BULLY) {
    if (flags.bullyTalked !== true) {
      flags.bullyTalked = true;
      narrate(
        "Bully",
        "Where do you think you're going? You better not make it.",
      );
    } else {
      narrate("Bully", "Still here. Still judging you.");
    }
    return;
  }
  if (npcId === PRINCIPAL) {
    if (held === "hall-pass") {
      narrate("Principal", "I see you have a hall pass. Very well — carry on.");
    } else {
      narrate(
        "Principal",
        "Running in the halls? This is not acceptable. Where is your hall pass?",
      );
      if (flags.principalGavePass !== true) {
        flags.principalGavePass = true;
        give("hall-pass", "The principal sighs and hands you a hall pass.");
      }
    }
    return;
  }
  if (npcId === TEACHER) {
    narrate(
      "Teacher",
      "You made it. Through that door — now. I will handle the paperwork.",
    );
  }
}

// ---------------------------------------------------------------------------
// Zone entry
// ---------------------------------------------------------------------------
function entered(zone: string): void {
  if (flags.finished === true) {
    return;
  }

  if (zone === BATHROOM) {
    ending(
      "Relieved",
      "You made it to the restroom just in time. " +
        "The teacher's expression when you walked back into class was priceless.",
    );
    return;
  }

  const spot = CHECKPOINTS[zone];
  if (spot !== undefined) {
    dispatch("player-checkpoint", {
      player: "",
      x: spot[0],
      z: spot[1],
      y: spot[2],
    });
    showCheckpoint(zone);
  }

  if (zone === STAIRS && flags.stairBeat !== true) {
    flags.stairBeat = true;
    dispatch("camera", {
      player: "",
      at: [30, 234, -8],
      look: [0, 210, -40],
      durationMs: 2_000,
      holdMs: 600,
      ease: "smooth",
    });
  }
  if (zone === CAFETERIA && flags.cafeBeat !== true) {
    flags.cafeBeat = true;
    dispatch("camera", {
      player: "",
      at: [30, 228, 88],
      look: [0, 218, 88],
      durationMs: 1_500,
      holdMs: 500,
      ease: "smooth",
    });
  }
  if (zone === MUD_ROOM && flags.mudBeat !== true) {
    flags.mudBeat = true;
    dispatch("camera", {
      player: "",
      at: [20, 228, 232],
      look: [0, 218, 232],
      durationMs: 1_500,
      holdMs: 500,
      ease: "smooth",
    });
  }
  if (zone === BATHROOM && flags.bathBeat !== true) {
    flags.bathBeat = true;
    dispatch("camera", {
      player: "",
      at: [30, 230, 280],
      look: [0, 218, 280],
      durationMs: 1_200,
      holdMs: 800,
      ease: "smooth",
    });
  }
}

// ---------------------------------------------------------------------------
// Hazard touches
// ---------------------------------------------------------------------------
function touched(entityId: string): void {
  if (entityId === "wet-floor") {
    dispatch("player-kill", { player: "", cause: "wet-floor" });
    return;
  }
  if (entityId === "globe") {
    dispatch("player-kill", { player: "", cause: "globe" });
  }
}

// ---------------------------------------------------------------------------
// Player death
// ---------------------------------------------------------------------------
function died(cause: string): void {
  deaths += 1;
  if (cause === "void") {
    narrate("You", "Fell all the way to the yard. That did not help.");
  } else if (cause === "wet-floor") {
    narrate("You", "The wet floor got me. Deaths so far: " + deaths + ".");
  } else if (cause === "globe") {
    narrate("You", "Knocked off by a library globe. Deaths: " + deaths + ".");
  } else {
    narrate("You", "Down again. Deaths: " + deaths + ".");
  }
}

// ---------------------------------------------------------------------------
// Main tick
// ---------------------------------------------------------------------------
onTick((_clockMs, events) => {
  if (!started) {
    started = true;
    open();
  }
  for (const event of events) {
    if (event.kind === "zone-entered" && event.zoneId !== undefined) {
      inZone[event.zoneId] = true;
      entered(event.zoneId);
      if (hinted[event.zoneId] !== true) {
        hinted[event.zoneId] = true;
        hintFor(event.zoneId);
      }
    } else if (event.kind === "zone-left" && event.zoneId !== undefined) {
      delete inZone[event.zoneId];
    } else if (event.kind === "entity-used" && event.entityId !== undefined) {
      used(event.entityId, event.item ?? "");
    } else if (event.kind === "item-used" && event.item !== undefined) {
      usedItem(event.item);
    } else if (event.kind === "npc-talk" && event.npcId !== undefined) {
      talked(event.npcId);
    } else if (
      event.kind === "player-touched" &&
      event.entityId !== undefined
    ) {
      touched(event.entityId);
    } else if (event.kind === "player-died") {
      died(event.cause ?? "");
    } else if (event.kind === "timer" && event.timerId === "bladder") {
      bladderBeat();
    }
  }
});
`,rP=`// The "A Dusty Trip" demo's place script — a small port of the Roblox driving
// survival game. It stands a sand plain and a road at boot, puts a car on it,
// and lets a player get in and steer. Fuel burns as the car travels; a dust
// storm chases from behind and bites anyone it overtakes; gas stations along
// the road refill the tank, and the distance driven is shown as a readout.
//
// The car is a solid seat prop the script drives itself: every tick it reads
// the local player's held input, steps a simple arcade body, and moves the prop
// with the velocity that carries whoever is standing on it. The storm is a
// scalar that closes on the car; the readouts are \`hud\` effects. Mutants are
// NPCs that chase whoever is nearest.
//
// ALL voxel coordinates × 2 = world coordinates. The plan handler takes voxel
// coordinates; props, NPCs, fields, and the player take world coordinates.
import {
  blocks,
  createNpc,
  createProp,
  createDecal,
  createStorm,
  dispatch,
  getHeightAt,
  getInput,
  getNow,
  getPlayers,
  getSolidAt,
  log,
  onPlan,
  onTick,
  type ModelsByName,
  type NpcHandle,
  type PropHandle,
  type StormHandle,
} from "voxelscape";

// ---------------------------------------------------------------------------
// Tuning
// ---------------------------------------------------------------------------
/** How often the trip steps, in milliseconds. */
const TICK_MS = 40;
const CAR_HEIGHT = 3;
const MAX_SPEED = 22;
const REVERSE_SPEED = 8;
const ACCEL = 16;
const BRAKE = 30;
const DRAG = 0.9;
const TURN_RATE = 1.7;
const FUEL_MAX = 60;
/** Litres burned per world unit travelled. */
const FUEL_PER_UNIT = 0.02;
const STORM_SPEED = 16;
/** Half the storm front's width, in world units; the span it bites across. */
const STORM_HALF_WIDTH = 40;
/** How close the storm front must be to sting, in world units. */
const STORM_REACH = 6;
const STORM_DAMAGE = 2;
/** Milliseconds between storm bites. */
const STORM_BITE_MS = 700;
/** Where the storm front begins, far enough behind that a stationary player has time to set off. */
const STORM_START_Z = -200;
/** How far behind the car the dust wall is invisible, in world units. */
const STORM_VISIBLE = 180;
const ZOMBIE_CAP = 8;
const ZOMBIE_SPEED = 3.2;
const ZOMBIE_DAMAGE = 2;
const ZOMBIE_ATTACK_MS = 1_000;
const ZOMBIE_ATTACK_RANGE = 3;
/** How long after the trip begins the first mutant appears, in milliseconds. */
const ZOMBIE_GRACE_MS = 15_000;
/** How far ahead of the car a mutant materializes, in world units. */
const ZOMBIE_SPAWN_AHEAD = 40;
/** The flat LOD-0 voxel top the road is graded to, near the terrain's base. */
const ROAD_LEVEL = 32;

// ---------------------------------------------------------------------------
// State
// ---------------------------------------------------------------------------
const CAR = "car";
const EXIT_BIND = "exit-car";
const FUEL_ITEM = "fuel";

let started = false;
let car: PropHandle<ModelsByName["platform"]> | null = null;
let x = 0;
let z = 0;
let y = 0;
let yaw = 0;
let speed = 0;
let fuel = FUEL_MAX;
let travelled = 0;
let driving = false;
let lastUseHeld = false;
let stormZ = STORM_START_Z;
let storm: StormHandle | null = null;
let lastBiteAt = 0;
let nextZombieAt = 0;
let zombieSeq = 0;
const zombies = new Map<
  string,
  { npc: NpcHandle<ModelsByName["zombie"]>; lastAttackAt: number }
>();

/** Sends the car prop to its current pose, carrying riders at its velocity. */
const moveCar = (): void => {
  car?.move({
    x,
    z,
    y,
    yaw,
    vx: Math.sin(yaw) * speed,
    vy: 0,
    vz: Math.cos(yaw) * speed,
  });
};

/** Shows the driving hint, fuel, and distance readouts to the local player. */
const showReadouts = (): void => {
  dispatch("hud", {
    player: "",
    id: "hint",
    kind: "text",
    label: "Controls",
    text: driving
      ? "Dig / W to accelerate · A D or stick to steer · R or use to get out"
      : "Walk to the car and use it to drive",
  });
  dispatch("hud", {
    player: "",
    id: "fuel",
    kind: "bar",
    label: "Fuel",
    value: Math.max(0, fuel),
    max: FUEL_MAX,
  });
  dispatch("hud", {
    player: "",
    id: "trip",
    kind: "text",
    label: "Distance",
    text: Math.round(travelled) + " m",
  });
};

/** Puts the local player in the driver's seat and hands them the wheel. */
const enterCar = (): void => {
  driving = true;
  dispatch("player-control", { player: "", locked: true });
  dispatch("player-place", { player: "", x, z, y: y + CAR_HEIGHT });
  dispatch("camera-follow", {
    player: "",
    entityId: CAR,
    back: 9,
    up: 4.5,
    lookAhead: 6,
  });
  dispatch("toast", { player: "", text: "Press R to get out." });
};

/** Puts the driver down beside the car and gives them back their body. */
const exitCar = (): void => {
  driving = false;
  dispatch("player-control", { player: "", locked: false });
  dispatch("camera-follow-clear", { player: "" });
  dispatch("player-place", {
    player: "",
    x: x + Math.cos(yaw) * 3,
    z: z - Math.sin(yaw) * 3,
  });
};

/** Steps the car one tick from the local player's held input. */
const driveTick = (dt: number): void => {
  const input = getInput();
  // Keyboard and the touch joystick both drive the movement axes; the touch
  // dig button held is a second accelerator, so a phone player can steer with
  // the stick and hold dig to go.
  const forward =
    input !== null && (input.moveY > 0.2 || (driving && input.primaryHeld));
  const reversing = input !== null && input.moveY < -0.2;
  const throttle = !driving ? 0 : forward ? 1 : reversing ? -1 : 0;
  const steer = driving && input !== null ? input.moveX : 0;
  const powered = fuel > 0 && throttle !== 0;

  if (powered) {
    speed += throttle > 0 ? throttle * ACCEL * dt : throttle * BRAKE * dt;
  }
  speed -= speed * DRAG * dt;
  speed = Math.max(-REVERSE_SPEED, Math.min(MAX_SPEED, speed));

  const grip = 0.25 + Math.min(1, Math.abs(speed) / 8);
  // A positive \`moveX\` is the driver's right, but the follow camera puts +x on
  // their left, so a right turn is the way yaw decreases.
  yaw -= steer * TURN_RATE * grip * dt;

  const nx = x + Math.sin(yaw) * speed * dt;
  const nz = z + Math.cos(yaw) * speed * dt;
  const aheadGround = getHeightAt(nx, nz);
  if (getSolidAt(nx, aheadGround + 1, nz)) {
    speed = 0;
  } else {
    travelled += Math.hypot(nx - x, nz - z);
    fuel = Math.max(0, fuel - Math.hypot(nx - x, nz - z) * FUEL_PER_UNIT);
    x = nx;
    z = nz;
    y = aheadGround;
  }
  moveCar();

  // A driver who falls off is set back on the seat, so a fast corner never
  // strands them behind the car.
  if (driving) {
    const me = getPlayers()[0];
    if (me !== undefined && Math.hypot(me.x - x, me.z - z) > 5) {
      dispatch("player-place", { player: "", x, z, y: y + CAR_HEIGHT });
    }
  }
};

/** Advances the storm and bites a player the front has caught. */
const stormTick = (dt: number, now: number): void => {
  // The front only ever moves forward: a driver who outruns it keeps their
  // lead, and one who stops is eventually overtaken.
  stormZ += STORM_SPEED * dt;
  dispatch("field", {
    id: "storm",
    kind: "push",
    min: [x - STORM_HALF_WIDTH, y - 8, stormZ - 30],
    max: [x + STORM_HALF_WIDTH, y + 12, stormZ],
    vz: STORM_SPEED,
  });
  // The wall stays centred on the car and fades in as the front closes, so a
  // driver who outruns it sees the dust settle back over the horizon.
  const intensity = Math.max(0, Math.min(1, 1 - (z - stormZ) / STORM_VISIBLE));
  storm?.move({
    x,
    z: stormZ - 15,
    y: getHeightAt(x, stormZ),
    yaw: 0,
    width: STORM_HALF_WIDTH,
    height: 20,
    depth: 30,
    intensity,
  });
  // The bite follows the player, not the car: a driver whose car is swallowed
  // while they stand clear is not in the dust, and a passenger on foot inside
  // the front is.
  const me = getPlayers()[0];
  const inStorm =
    me !== undefined &&
    me.z - stormZ < STORM_REACH &&
    Math.abs(me.x - x) < STORM_HALF_WIDTH;
  if (inStorm && now - lastBiteAt >= STORM_BITE_MS) {
    lastBiteAt = now;
    dispatch("player-damage", {
      player: "",
      amount: STORM_DAMAGE,
      source: "storm",
    });
  }
};

/** Materializes a mutant ahead of the car and walks the tracked ones in. */
const zombiesTick = (dt: number, now: number): void => {
  if (zombies.size < ZOMBIE_CAP && now >= nextZombieAt) {
    nextZombieAt = now + 6_000;
    const zx = x + 8;
    const zz = z + ZOMBIE_SPAWN_AHEAD;
    const id = "mutant-" + zombieSeq++;
    zombies.set(id, {
      npc: createNpc({
        model: "zombie",
        id,
        x: zx,
        z: zz,
        y: getHeightAt(zx, zz),
        name: "Mutant",
      }),
      lastAttackAt: 0,
    });
  }
  const me = getPlayers()[0];
  if (me === undefined) {
    return;
  }
  for (const [, zombie] of zombies) {
    const dx = me.x - zombie.npc.x;
    const dz = me.z - zombie.npc.z;
    const distance = Math.hypot(dx, dz);
    if (distance < ZOMBIE_ATTACK_RANGE) {
      if (now - zombie.lastAttackAt >= ZOMBIE_ATTACK_MS) {
        zombie.lastAttackAt = now;
        dispatch("player-damage", {
          player: "",
          amount: ZOMBIE_DAMAGE,
          source: zombie.npc.id,
        });
      }
      continue;
    }
    const step = ZOMBIE_SPEED * dt;
    const heading = Math.atan2(dx, dz);
    const nx = zombie.npc.x + (dx / distance) * step;
    const nz = zombie.npc.z + (dz / distance) * step;
    zombie.npc.move({
      x: nx,
      z: nz,
      y: getHeightAt(nx, nz),
      yaw: heading,
      live: true,
    });
  }
};

/** Reorders the trip's tick timer. */
const armTick = (): void => {
  dispatch("timer", { id: "trip-tick", afterMs: TICK_MS });
};

// ---------------------------------------------------------------------------
// The desert the trip drives across: an endless sand skin over the region's
// terrain, with an endless road-width strip of greystone graded flat through
// it so the car never climbs a hill.
// ---------------------------------------------------------------------------
onPlan(() => {
  const b = blocks;
  return JSON.stringify([
    {
      kind: "surface",
      reachX: "infinite",
      reachZ: "infinite",
      depth: 2,
      id: b.sand,
    },
    {
      kind: "surface",
      min: [-4, 0, 0],
      max: [4, 0, 0],
      reachZ: "infinite",
      level: ROAD_LEVEL,
      depth: 1,
      id: b.greystone,
    },
  ]);
});

